  {"prompt": "Συνώνυμο/ορισμός: οχυρωμένα σημεία ενός τείχους που προεξέχουν", "options": [], "answer": "προμαχώνες", "answer_note": "ο προμαχώνας = bastion."},
  {"prompt": "Συνώνυμο/ορισμός: μάχη ανάμεσα σε πλοία", "options": [], "answer": "ναυμαχία", "answer_note": "η ναυμαχία = naval battle."},
  {"prompt": "Συνώνυμο/ορισμός: έκανε πιο γρήγορη", "options": [], "answer": "επιτάχυνε", "answer_note": "επιταχύνω = to speed up, hasten."},
